#include "audio_preferences.h"
#include <iostream>
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;auto p=std::filesystem::path(argv[1]);whic::AudioPreferences x,y;std::wstring e;int n=0;auto check=[&](bool b){if(!b)++n;};check(whic::loadPreferences(p,x,e)&&x.backend=="wasapi-shared");x.backend="asio";x.driver="{B979B4A6-691F-4490-9C62-7811B5A3AEF5}";check(whic::savePreferences(p,x,e));check(whic::loadPreferences(p,y,e)&&y.backend==x.backend&&y.driver==x.driver);for(auto kind:{"wasapi-shared","wasapi-exclusive"}){x.backend=kind;x.endpoint="endpoint-test";check(whic::savePreferences(p,x,e)&&whic::loadPreferences(p,y,e)&&y.backend==kind&&y.endpoint==x.endpoint);}x.backend="invalid";check(!whic::savePreferences(p,x,e));check(whic::loadPreferences(p,y,e)&&y.backend=="wasapi-exclusive");{std::ofstream f(p);f<<"WHIC_AUDIO_1 \"asio\" \"invalid-guid\" \"\"";}check(!whic::loadPreferences(p,y,e));{std::ofstream f(p);f<<"WHIC_AUDIO_1 \"wasapi-shared\" \"\" \"\" unexpected";}check(!whic::loadPreferences(p,y,e));std::filesystem::remove(p);std::wcout<<L"Preferences tests failures: "<<n<<L"; no audio APIs called\n";return n?1:0;}
